const esc = (s) => s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
const markup = (src) => esc(src).replace(/«(\w+):([^»]*)»/g, (m, r, t) => `<span class="${r}">${t}</span>`);
const splitChars = (el, text) => { el.innerHTML = [...text].map((ch) => `<span class="ch">${ch === " " ? "&nbsp;" : esc(ch)}</span>`).join(""); return $$(".ch", el); };

// ---------- state ----------
let palettes = [], current = -1, world = null;
const live = { css: {}, colors: {}, nums: {} };

function applyCss(vars) {
  const st = document.documentElement.style;
  for (const [k, v] of Object.entries(vars)) st.setProperty(`--${k}`, v);
}
function writeWorld() {
  if (!world) return;
  for (const [k, v] of Object.entries(live.colors)) world.state.colors[k].set(v);
  Object.assign(world.state.nums, live.nums);
}

// Retargetable transitions: live values continuously chase the current target, with a
// frame-rate-independent rate. Racing through five sets just bends the path toward the
// newest one; nothing restarts, nothing snaps.
const CHASE_RATE = 3.4; // per second; ~1s to settle
let target = null, chasing = 0, lastChase = 0;
function chase(now) {
  const dt = Math.min(0.05, (now - lastChase) / 1000 || 0.016);
  lastChase = now;
  const k = 1 - Math.exp(-dt * CHASE_RATE);
  let moving = false;
  for (const k2 in target.css) { const a = live.css[k2], b = target.css[k2]; if (a !== b) { const n = a ? mix(a, b, k) : b; live.css[k2] = n === a ? b : n; moving = true; } }
  for (const k2 in target.colors) { const a = live.colors[k2], b = target.colors[k2]; if (a !== b) { const n = a ? mix(a, b, k) : b; live.colors[k2] = n === a ? b : n; moving = true; } }
  for (const k2 in target.nums) { const a = live.nums[k2], b = target.nums[k2]; if (a !== b) { live.nums[k2] = a === undefined || Math.abs(b - a) < 1e-3 ? b : a + (b - a) * k; moving = true; } }
  applyCss(live.css);
  writeWorld();
  chasing = moving ? requestAnimationFrame(chase) : 0;
}

function setSet(i, { instant = false } = {}) {
  if (i === current || !palettes[i]) return;
  current = i;
  const p = palettes[i], w = worldFor(p);
  target = { css: p.colors, colors: w.colors, nums: w.nums };
  if (instant || reducedMotion) {
    Object.assign(live.css, target.css); Object.assign(live.colors, target.colors); Object.assign(live.nums, target.nums);
    applyCss(live.css); writeWorld();
  } else if (!chasing) { lastChase = performance.now(); chasing = requestAnimationFrame(chase); }
  // lightning cracks as the set changes; the clock takes the new set's tempo
  if (!instant && world) world.strike(w.colors.flash);
  beat.bpm = w.nums.bpm;
  beatUI();
  document.documentElement.style.colorScheme = p.meta.appearance;
  $("#np-name").textContent = `${p.meta.time} · ${p.meta.name}`;
  $$(".chip[data-i]").forEach((c) => c.setAttribute("aria-pressed", String(+c.dataset.i === i)));
  drawBars(p);
  terminal(p);
  lineupText(i);
}

// ---------- lineup ----------
let lineupShown = -1;
function lineupText(i) {
  if (i === lineupShown) return;
  lineupShown = i;
  const p = palettes[i];
  $$(".rail button").forEach((b, j) => b.classList.toggle("on", j === i));
  const chars = splitChars($("#set-time"), p.meta.time);
  $("#set-name").innerHTML = `${esc(p.meta.name)} <span class="room">· ${esc(p.meta.set)}</span>`;
  $("#set-tagline").textContent = p.meta.tagline;
  $("#set-dots").innerHTML = ["pink", "afterglow", "cyan", "brass", "sunset", "uv", "brassLight", "lavender"].map((k) => `<span style="background:${p.colors[k]};color:${p.colors[k]}" title="${p.colors[k]}"></span>`).join("");
  $("#set-file").textContent = `${p.meta.slug}.tsx`;
  if (reducedMotion || !anime) return;
  anime.remove(chars);
  anime({ targets: chars, translateY: ["0.9em", 0], opacity: [0, 1], rotate: [8, 0], delay: anime.stagger(55), duration: 900, easing: "easeOutExpo" });
  anime({ targets: ["#set-name", "#set-tagline", "#set-dots", ".set-card"], translateY: [18, 0], opacity: [0, 1], delay: anime.stagger(70, { start: 120 }), duration: 800, easing: "easeOutQuart" });
}
function buildLineup() {
  $("#rail").insertAdjacentHTML("beforeend", palettes.map((p, i) => `<button data-i="${i}"><b>${p.meta.time}</b>${esc(p.meta.name)}</button>`).join(""));
  $("#set-code").innerHTML = markup(SAMPLES.ts.src.split("\n").slice(0, 9).join("\n"));
  $("#lineup").style.setProperty("--sets", palettes.length);
  $$(".rail button").forEach((b) => b.addEventListener("click", () => {
    goTo(layout.top + layout.span * ((+b.dataset.i + 0.5) / palettes.length));
  }));
}

// ---------- scroll → store ----------
// Layout is measured once per resize, never during scroll (no forced reflows mid-frame).
const layout = { top: 0, span: 1 };
function measure() {
  const sec = $("#lineup");
  layout.top = sec.offsetTop;
  layout.span = Math.max(1, sec.offsetHeight - innerHeight);
}
function onScroll(y, velocity = 0) {
  const prog = (y - layout.top) / layout.span;
  const s = store.get(), n = palettes.length;
  let set = s.set;
  if (prog < 0) set = home;
  else if (prog <= 1) {
    // hysteresis: hovering on a boundary doesn't flicker between two sets
    const raw = prog * n, HYST = 0.12;
    const inLineup = s.set >= 0 && s.lineup >= 0 && s.lineup <= 1;
    if (!inLineup || raw < s.set - HYST || raw > s.set + 1 + HYST) set = Math.min(n - 1, Math.floor(raw));
  }
  store.set({ y, velocity, lineup: prog, set });
}
let home = 0, lenis = null;
const goTo = (target) => (lenis ? lenis.scrollTo(target, { duration: 1.6 }) : scrollTo({ top: target, behavior: reducedMotion ? "auto" : "smooth" }));

// ---------- playground ----------
let lang = "ts";
function renderCode(animate) {
  const s = SAMPLES[lang];
  $("#ed-file").textContent = s.file;
  const lines = markup(s.src).split("\n");
  $("#code").innerHTML = lines.map((l, i) => `<span class="ln${i === s.cur ? " cur" : ""}">${l || " "}${i === s.cur ? '<span class="caret"></span>' : ""}</span>`).join("");
  if (animate && !reducedMotion && anime) anime({ targets: "#code .ln", opacity: [0, 1], translateX: [-8, 0], delay: anime.stagger(28), duration: 500, easing: "easeOutQuad" });
}
function terminal(p) {
  const c = p.colors, sp = (k, t) => `<span style="color:${c[k]}">${esc(t)}</span>`;
  const sw = (keys) => keys.map((k) => `<span class="sw" style="background:${c[k]}"></span>`).join("");
  $("#term").innerHTML =
    `${sp("pink", "❯")} ${sp("cyan", "npm")} run check\n` +
    `${sp("lime", "ok")}: every generated file up to date\n` +
    palettes.map((q) => `${sp(q === p ? "brass" : "comment", q.meta.name)}: ${sp("lime", "pass")}`).join("   ") + "\n" +
    sw(["ansiBlack", "red", "lime", "brass", "blue", "pink", "cyan", "ansiWhite"]) + "  " + sw(["comment", "redLight", "limeLight", "brassLight", "blueLight", "pinkLight", "cyanLight", "brightWhite"]);
}
function tilt() {
  const ed = $("#editor");
  if (reducedMotion) return;
  $(".editor-wrap").addEventListener("pointermove", (e) => {
    const r = ed.getBoundingClientRect(), x = (e.clientX - r.left) / r.width - 0.5, y = (e.clientY - r.top) / r.height - 0.5;
    ed.style.transform = `rotateX(${(-y * 4).toFixed(2)}deg) rotateY(${(x * 5).toFixed(2)}deg)`;
  });
  $(".editor-wrap").addEventListener("pointerleave", () => (ed.style.transform = ""));
}

// ---------- proof ----------
const ROLES = [["keywords", "pink"], ["strings", "afterglow"], ["functions", "cyan"], ["types", "brass"], ["params", "brassLight"], ["generics", "peach"], ["numbers", "sunset"], ["namespaces", "uv"], ["properties", "lavender"], ["operators", "orchid"], ["comments", "comment"], ["text", "textEditor"]];
function buildBars() {
  $("#bars").insertAdjacentHTML("beforeend", ROLES.map(([label]) => `<div class="barrow"><span>${label}</span><div class="track"><div class="fillbar"></div><i class="aa"></i></div><b>–</b></div>`).join(""));
}
function drawBars(p) {
  const max = 21;
  $("#bars-set").textContent = `${p.meta.name} · on ${p.colors.base}`;
  $$(".barrow").forEach((row, i) => {
    const key = ROLES[i][1], r = contrast(p.colors[key], p.colors.base);
    const floor = p.meta.contrastFloor || 4.5;
    row.querySelector(".aa").style.left = `${(floor / max) * 100}%`;
    row.querySelector("b").textContent = r.toFixed(1);
    const bar = row.querySelector(".fillbar");
    bar.style.background = p.colors[key];
    bar.style.boxShadow = `0 0 14px -2px ${p.colors[key]}`;
    const w = `${Math.min(100, (r / max) * 100)}%`;
    if (reducedMotion || !anime) bar.style.width = w;
    else { anime.remove(bar); anime({ targets: bar, width: w, duration: 1200, delay: i * 40, easing: "easeOutExpo" }); }
  });
}

// ---------- reveals ----------
function reveals() {
  if (reducedMotion || !anime) { document.documentElement.classList.add("no-motion"); return; }
  const io = new IntersectionObserver((entries) => {
    for (const e of entries) {
      if (!e.isIntersecting) continue;
      io.unobserve(e.target);
      anime({ targets: e.target, translateY: [36, 0], opacity: [0, 1], duration: 1100, easing: "easeOutExpo", delay: +(e.target.dataset.delay || 0) });
      if (e.target.id === "proof-number") anime({ targets: { n: 0 }, n: +$("#count").textContent, round: 1, duration: 2200, easing: "easeOutExpo", update: (a) => ($("#count").textContent = a.animations[0].currentValue) });
    }
  }, { threshold: 0.18 });
  $$(".reveal").forEach((el) => io.observe(el));
}

function hero() {
  const lines = $$(".wordmark .line");
  lines.forEach((l) => splitChars(l, l.textContent));
  $$(".wordmark .line")[1].querySelectorAll(".ch").forEach((c) => c.classList.add("accent"));
  if (reducedMotion || !anime) return;
  anime.timeline({ easing: "easeOutExpo" })
    .add({ targets: ".wordmark .ch", translateY: ["105%", 0], rotate: [6, 0], duration: 1500, delay: anime.stagger(45) })
    .add({ targets: [".hero .eyebrow", ".hero-sub p", ".hero .btns .btn", ".scroll-cue"], opacity: [0, 1], translateY: [20, 0], duration: 1000, delay: anime.stagger(90) }, "-=1100");
}

// ---------- assorted ----------
function marquee() {
  const rows = [
    ["VS Code", "Cursor", "VSCodium", "Zed", "Neovim", "Helix", "Sublime Text", "JetBrains", "T3 Code"],
    ["Windows Terminal", "Ghostty", "WezTerm", "Kitty", "Alacritty", "iTerm2", "bat", "delta", "fzf", "Starship", "Obsidian", "Discord", "Firefox", "Slack", "Raycast"],
  ];
  $$(".marquee .track-row").forEach((row, i) => {
    const pills = rows[i].map((n, j) => `<span class="pill">${n}<em>${palettes[j % palettes.length].meta.time}</em></span>`).join("");
    row.innerHTML = pills + pills;
  });
}
function walls() {
  $("#walls").innerHTML = palettes.map((p) => `<a class="wall reveal" href="wallpapers/${p.meta.slug}-desktop.png" download><img loading="lazy" src="wallpapers/thumbs/${p.meta.slug}.png" alt="${esc(p.meta.name)} wallpaper"><figcaption>${esc(p.meta.name)}<small>4K · phone</small></figcaption></a>`).join("");
}
function eq() {
  const keys = ["pink", "brass", "cyan", "afterglow", "sunset", "uv", "lime", "peach"];
  $("#eq").innerHTML = Array.from({ length: 36 }, (_, i) => `<span style="background:var(--${keys[i % keys.length]});animation-delay:${(-(i * 0.137) % 1.6).toFixed(2)}s;animation-duration:${(1.2 + ((i * 7) % 9) / 10).toFixed(2)}s"></span>`).join("");
}
function copies() {
  document.addEventListener("click", (e) => {
    const btn = e.target.closest(".copy");
    if (!btn) return;
    const text = btn.parentElement.textContent.replace(btn.textContent, "").trim();
    navigator.clipboard?.writeText(text);
    const t = $("#toast");
    t.textContent = "Copied";
    t.classList.add("show");
    setTimeout(() => t.classList.remove("show"), 1400);
  });
}

// ---------- boot ----------
async function boot() {
  palettes = await (await fetch("palettes.json")).json();
  home = palettes.findIndex((p) => p.meta.slug === "4am");
  try {
    const { createWorld } = await import("./scene.js");
    world = createWorld($("#world"), { reducedMotion, store, beat });
  } catch (err) {
    console.warn("WebGL world unavailable, using the painted sky", err);
    $("#world").remove();
    document.body.insertAdjacentHTML("afterbegin", '<div class="fallback-sky" aria-hidden="true"></div>');
  }
  buildLineup();
  buildBars();
  $("#chips").innerHTML = palettes.map((p, i) => `<button class="chip" data-i="${i}"><small>${p.meta.time}</small>${esc(p.meta.name)}</button>`).join("");
  $$(".chip[data-i]").forEach((c) => c.addEventListener("click", () => store.set({ set: +c.dataset.i })));
  $$("#lang button").forEach((b) => b.addEventListener("click", () => {
    lang = b.dataset.lang;
    $$("#lang button").forEach((x) => x.setAttribute("aria-pressed", String(x === b)));
    renderCode(true);
  }));
  $("#italics").addEventListener("change", (e) => $("#editor").classList.toggle("noital", !e.target.checked));
  renderCode(false);
  marquee();
  walls();
  eq();
  copies();
  tilt();
  // the store is the single source of truth; the page and the world subscribe to it
  setSet(home, { instant: true });
  store.set({ set: home });
  store.select((s) => s.set, (i) => setSet(i));
  store.select((s) => s.y > 40, (on) => $("header.nav").classList.toggle("scrolled", on));
  store.select((s) => Math.round(Math.max(0, Math.min(1, s.lineup)) * 1000), (v) => ($("#rail-fill").style.height = `${v / 10}%`));
  if (world) world.start();
  beatControls();
  cursorRing({ reducedMotion });
  hero();
  reveals();

  measure();
  addEventListener("resize", measure);
  new ResizeObserver(measure).observe(document.body);
  if (!reducedMotion) {
    try {
      const { default: Lenis } = await import("lenis");
      // Wheel feel: light inertia (lerp) so it stays responsive, and a per-event ceiling so a
      // hard flick has a top speed. Slow scrolls and trackpads (small deltas) pass untouched.
      const WHEEL_MAX = 140;
      lenis = new Lenis({
        lerp: 0.11,
        smoothWheel: true,
        wheelMultiplier: 1,
        touchMultiplier: 1.4,
        virtualScroll: (e) => {
          if (e.event.type === "wheel") e.deltaY = Math.max(-WHEEL_MAX, Math.min(WHEEL_MAX, e.deltaY));
          return true;
        },
      });
      lenis.on("scroll", (l) => onScroll(l.scroll, l.velocity));
      const raf = (t) => { lenis.raf(t); requestAnimationFrame(raf); };
      requestAnimationFrame(raf);
      // in-page anchors glide too
      document.addEventListener("click", (e) => {
        const a = e.target.closest('a[href^="#"]');
        if (!a) return;
        const el = a.getAttribute("href") === "#top" ? 0 : $(a.getAttribute("href"));
        if (el === null) return;
        e.preventDefault();
        lenis.scrollTo(el, { duration: 1.6 });
      });
    } catch (err) {
      console.warn("smooth scroll unavailable", err);
    }
  }
  if (!lenis) addEventListener("scroll", () => onScroll(scrollY), { passive: true });
  onScroll(scrollY);
  document.body.classList.add("ready");

  // ?y=3.5 jumps 3.5 viewport heights down (handy for screenshots and deep links)
  const y = new URLSearchParams(location.search).get("y");
  if (y) { lenis ? lenis.scrollTo(+y * innerHeight, { immediate: true }) : scrollTo(0, +y * innerHeight); onScroll(+y * innerHeight); }
  if (new URLSearchParams(location.search).has("debug")) debugHud();
}

// ---------- beat mode ----------
function beatUI() {
  const btn = $("#beat-toggle");
  if (!btn) return;
  const on = beat.mode !== "off";
  btn.setAttribute("aria-pressed", String(on));
  $("#np-bpm").textContent = beat.mode === "listen" ? (beat.source === "mic" ? "· mic" : "· live") : on ? `· ${beat.bpm} bpm` : "";
  $("#listen").textContent = beat.mode === "listen" ? "Stop syncing" : "Sync to my music";
}
function beatControls() {
  if (reducedMotion || !world) {
    $("#beat-toggle").disabled = true;
    $("#listen").closest(".sync").hidden = true;
    return;
  }
  beat.onBeat = () => {
    const d = $(".now-playing .dot");
    d.classList.remove("hit");
    void d.offsetWidth;
    d.classList.add("hit");
  };
  beat.onEnd = () => { $("#listen-note").textContent = "Sharing stopped. The clock is still here."; beatUI(); };
  $("#beat-toggle").addEventListener("click", () => { beat.mode === "off" ? beat.useClock(true) : beat.stop(); beatUI(); });
  $("#listen").addEventListener("click", async () => {
    if (beat.mode === "listen") { beat.stop(); beatUI(); return; }
    try {
      const src = await beat.listen();
      $("#listen-note").textContent = src === "system" ? "Listening to your shared audio. Stop sharing whenever you like." : "Listening through your microphone. Turn the music up.";
    } catch {
      $("#listen-note").textContent = "No audio shared. The built-in clock still keeps time.";
    }
    beatUI();
  });
  beatUI();
}

// ?debug: live fps, render scale, active set, scroll velocity
function debugHud() {
  const hud = document.createElement("div");
  hud.style.cssText = "position:fixed;left:12px;bottom:12px;z-index:50;font:12px/1.5 var(--mono);padding:8px 12px;border-radius:10px;background:var(--glass-strong);border:1px solid var(--hairline);pointer-events:none;white-space:pre";
  document.body.appendChild(hud);
  let frames = 0, last = performance.now();
  const tick = (now) => {
    frames++;
    if (now - last > 500) {
      const s = store.get();
      hud.textContent = `fps ${Math.round((frames * 1000) / (now - last))}\nscale ${world ? world.quality : "–"}\nset ${palettes[s.set]?.meta.name}\nvelocity ${s.velocity.toFixed(1)}`;
      frames = 0;
      last = now;
    }
    requestAnimationFrame(tick);
  };
  requestAnimationFrame(tick);
}
boot();
